# scan A: the instrument lists of Dan 3:5 and 3:7 in both witnesses
import re
SP = r"C:\wt\logos-t423-m8-fable\.ai\scratch\multi_model_bible_chunking\M8_fable\sp_durable"
o = {}
for l in open(SP + r"\Dan\Dan_oshb.txt", "rb").read().decode("utf-8").split("\n"):
    if "\t" in l:
        k, t = l.split("\t", 1); o[k] = t.split(" ")
def sk(w): return "".join(c for c in w if "\u05d0" <= c <= "\u05ea")
a = [sk(w) for w in o["Dan.3.5"][4:10]]; b = [sk(w) for w in o["Dan.3.7"][10:15]]
print("oshb 3:5 words 5-10:", len(a), a)
print("oshb 3:7 words 11-15:", len(b), b)
print("oshb 3:5 word 11:", sk(o["Dan.3.5"][10]), "| oshb 3:7 word 16:", sk(o["Dan.3.7"][15]))
print("3:5 names by position absent from 3:7:", [(i + 1, x) for i, x in enumerate(a) if x not in b])
w = {}; ch = None; cur = None
for l in open(SP + r"\Dan\Dan_web_clean.txt", "rb").read().decode("utf-8").split("\n"):
    m = re.match(r"===== DAN (\d+) =====", l)
    if m: ch = int(m.group(1)); continue
    m = re.match(r"\[v\] (\d+) (.*)", l)
    if m: cur = (ch, int(m.group(1))); w[cur] = m.group(2); continue
    if cur and l.strip() and l.strip() != "\u00b6": w[cur] += " " + l.strip()
for v in (5, 7):
    m = re.search(r"sound of the (.*?), and all kinds of music", w[(3, v)])
    print("web 3:%d list:" % v, m.group(1).split(", "))

# scan B: which device-inventory lists hold the verses beside the rival seam (MT face)
import json
SP = r"C:\wt\logos-t423-m8-fable\.ai\scratch\multi_model_bible_chunking\M8_fable\sp_durable"
d = json.loads(open(SP + r"\Dan\dan_device_inventory.json", "rb").read().decode("utf-8"))
hits = {}; nlists = [0]
def walk(x, path):
    if isinstance(x, dict):
        for k, v in x.items(): walk(v, path + [k])
    elif isinstance(x, list):
        if path and path[-1].startswith("verses_mt"): nlists[0] += 1
        for i in x:
            if isinstance(i, str) and i in ("Dan.4.19", "Dan.4.20", "Dan.4.21"):
                hits.setdefault(i, []).append("/".join(path))
            elif isinstance(i, (dict, list)): walk(i, path + ["[]"])
    elif isinstance(x, str) and x in ("Dan.4.19", "Dan.4.20", "Dan.4.21"):
        hits.setdefault(x, []).append("/".join(path))
walk(d, [])
print("verses_mt lists walked:", nlists[0])
for v in ("Dan.4.19", "Dan.4.20", "Dan.4.21"): print(v, "->", hits.get(v, []))

